def get_encrypted_known():
    # Connect to service and get encrypted form of known plaintext
    r = remote('crypto.chal.csaw.io', 5000)
    r.sendlineafter(b'Enter your password: ', KNOWN_PLAIN.encode())
    response = r.recvall().decode()
    r.close()

    # Extract the encrypted form
    start = response.find('Encrypted: ') + len('Encrypted: ')
    encrypted = response[start:].strip()
    return bytes.fromhex(encrypted)

def derive_key(plain, encrypted):
    # XOR plaintext with its encrypted form to get key
    return bytes(p ^ c for p, c in zip(plain.encode(), encrypted))

def decrypt(encrypted, key):
    # XOR encrypted data with key
    result = []
    for i in range(0, len(encrypted), len(key)):
        chunk = encrypted[i:i+len(key)]
        result.extend(c ^ k for c, k in zip(chunk, key))
    return bytes(result)

def main():
    # Step 1: Get encrypted form of known plaintext
    print("[*] Getting encrypted form of known plaintext...")
    encrypted_known = get_encrypted_known()

    # Step 2: Derive the key
    key = derive_key(KNOWN_PLAIN, encrypted_known)

    # Step 3: Read encrypted passwords
    with open('encrypted_passwords.txt', 'rb') as f:
